ALTER TABLE public.orders ADD COLUMN cancelled boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.guest_cancel_order(_token uuid,_device uuid,_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); UPDATE orders SET cancelled=true WHERE id=_order AND booking_id=b.id AND status IN ('pending','in_progress') AND NOT cancelled; IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_CANCELLABLE'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.guest_orders(_token uuid,_device uuid) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; result json; BEGIN b:=require_guest(_token,_device); SELECT coalesce(json_agg(q),'[]'::json) INTO result FROM (SELECT id,type,details,CASE WHEN cancelled THEN 'cancelled' ELSE status END AS status,created_at FROM orders WHERE booking_id=b.id ORDER BY created_at DESC LIMIT 20) q; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.staff_set_order_status(_pin text,_order uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _status NOT IN ('pending','in_progress','done') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF; UPDATE orders SET status=_status WHERE id=_order AND NOT cancelled AND status <> 'done'; END $$;